package steps

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
)

//truebdd:concept when "doubling"
func concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b(state *State, args []string) error {
	number := args[0]

	if _, err := strconv.Atoi(number); err != nil {
		return fmt.Errorf("the step's whole number %q is not an integer literal: %w", number, err)
	}

	if state.CalcPath == "" {
		return fmt.Errorf("no calculator program was kept by the installation Given; the doubling step needs it to run double %s", number)
	}

	hostRoot, err := filepath.Abs(filepath.Join("..", ".."))
	if err != nil {
		return fmt.Errorf("locate the host root: %w", err)
	}

	run := exec.Command(state.CalcPath, "double", number)
	run.Dir = hostRoot
	run.Env = os.Environ()

	var stderr strings.Builder
	run.Stderr = &stderr

	stdout, err := run.Output()
	if err != nil {
		return fmt.Errorf("run %s double %s from %s: %w: %s", state.CalcPath, number, hostRoot, err, strings.TrimSpace(stderr.String()))
	}

	printed := strings.TrimSpace(string(stdout))
	doubled, err := strconv.Atoi(printed)
	if err != nil {
		return fmt.Errorf("%s double %s printed %q on stdout, which is not the doubled integer the Calculator CLI declares: %w", state.CalcPath, number, printed, err)
	}

	state.Doubled = doubled
	state.DoubledSet = true
	return nil
}

package steps

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

//truebdd:concept given "installation"
func conceptbef0930c9a09dec2b565c664833e27eb5e85810f2e50d51372923cf970aa997c(state *State, args []string) error {
	hostRoot, err := filepath.Abs(filepath.Join("..", ".."))
	if err != nil {
		return fmt.Errorf("locate the host root: %w", err)
	}

	buildDir, err := os.MkdirTemp("", "calc-install-")
	if err != nil {
		return fmt.Errorf("make a build directory under the host's tmp directory: %w", err)
	}

	program := filepath.Join(buildDir, "calc")

	build := exec.Command("go", "build", "-o", program, "./services/calc")
	build.Dir = hostRoot
	build.Env = os.Environ()
	if out, err := build.CombinedOutput(); err != nil {
		return fmt.Errorf("build the calculator from ./services/calc at %s: %w: %s", hostRoot, err, strings.TrimSpace(string(out)))
	}

	if _, err := os.Stat(program); err != nil {
		return fmt.Errorf("the built calculator program is not at %s: %w", program, err)
	}

	state.CalcPath = program
	return nil
}

package steps

import (
	"fmt"
	"strconv"
)

//truebdd:concept then "result"
func concepted1de9371d2a7b37ce77d82464ab6737cf25f6c86f592518873001398dd1313e(state *State, args []string) error {
	expectedText := args[0]

	expected, err := strconv.Atoi(expectedText)
	if err != nil {
		return fmt.Errorf("the step's expected whole number %q is not an integer literal: %w", expectedText, err)
	}

	if !state.DoubledSet {
		return fmt.Errorf("no stdout of the calculator's double command was kept by the doubling When; the result step cannot observe the printed whole number it expects to be %d", expected)
	}

	if state.Doubled != expected {
		return fmt.Errorf("the calculator's double command printed %d on stdout, want %d", state.Doubled, expected)
	}

	return nil
}

package steps

func Register(suite interface {
	Step(string, func(*State, []string) error)
}) {
	suite.Step("^the calculator (?:is|has been) installed$", conceptbef0930c9a09dec2b565c664833e27eb5e85810f2e50d51372923cf970aa997c)

	suite.Step("^the Owner doubles (-?\\d+)$", concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b)

	suite.Step("^the result is (-?\\d+)$", concepted1de9371d2a7b37ce77d82464ab6737cf25f6c86f592518873001398dd1313e)
}

package steps

// State carries what one scenario's steps share.
type State struct {
	// CalcPath is the path of the calculator program built by the
	// installation Given, kept for the When to run.
	CalcPath string

	// Doubled is the integer the kept calculator program's double
	// command printed on stdout, kept by the doubling When for the
	// result Then to observe.
	Doubled int

	// DoubledSet records that the doubling When ran the double command
	// and kept its integer stdout in Doubled.
	DoubledSet bool
}
